mapper.select:
SELECT o.*
FROM customer_order o
WHERE o.is_delete = 0
  AND o.is_cancel = 0
  AND o.project_no = #{projectNo}
  AND o.create_time BETWEEN #{dayStart} AND #{dayEnd}
  AND (o.transaction_type IS NULL OR o.transaction_type <> 3) 

    AND o.order_no IN

        #{orderNo}


  AND o.id > #{startId}
  AND NOT EXISTS (
      SELECT 1
      FROM replace_battery_device_flow f
      WHERE f.order_no = o.order_no
        AND f.is_delete = 0
  )
ORDER BY o.id
LIMIT #{pageSize}

SELECT DISTINCT r.id, r.order_no FROM customer_order r JOIN replace_battery_device_flow f ON f.order_no = r.source_order_no AND f.is_delete = 0 WHERE r.is_delete = 0 AND r.is_cancel = 0 AND r.sub_type = 3001 AND r.status = 4 AND f.create_time BETWEEN #{dayStart} AND #{dayEnd}
AND EXISTS ( SELECT 1 FROM customer_order p WHERE p.order_no = r.source_order_no AND p.is_delete = 0 AND p.is_cancel = 0 )
AND r.source_order_no IN
#{orderNo}
AND r.id > #{startId} AND f.flow_status >= 40 AND f.flow_status <> 60 AND (f.refund_order_no IS NULL OR FIND_IN_SET(r.order_no, f.refund_order_no) = 0) ORDER BY r.id LIMIT #{pageSize}

SELECT f.id, f.order_no AS orderNo, o.status AS orderStatus, o.cserial_no AS cserialNo FROM replace_battery_device_flow f JOIN customer_order o ON o.order_no = f.order_no AND o.is_delete = 0 AND o.is_cancel = 0 WHERE f.is_delete = 0 AND f.create_time BETWEEN #{dayStart} AND #{dayEnd}
AND f.order_no IN
#{orderNo}
AND f.id > #{startId} AND o.status <> 1
AND ( o.status <> f.trade_status OR f.flow_status < CASE WHEN o.status = 2 THEN 20 WHEN o.status = 3 AND (o.cserial_no IS NULL OR o.cserial_no = '') THEN 60 ELSE 30 END ) ORDER BY f.id LIMIT #{pageSize}

SELECT f.* FROM replace_battery_device_flow f JOIN customer_order o ON o.order_no = f.order_no AND o.is_delete = 0 AND o.is_cancel = 0 WHERE f.is_delete = 0 AND f.flow_status = 30 AND f.create_time BETWEEN #{dayStart} AND #{dayEnd} AND o.share_status = 4
AND f.order_no IN
#{orderNo}
AND f.id > #{startId} AND EXISTS ( SELECT 1 FROM customer_order_asinfo a WHERE a.order_no = f.order_no AND a.is_delete = 0 AND a.payment_status = 4 ) AND NOT EXISTS ( SELECT 1 FROM customer_order_asinfo a WHERE a.order_no = f.order_no AND a.is_delete = 0 AND (a.payment_status IS NULL OR a.payment_status <> 4) ) ORDER BY f.id LIMIT #{pageSize}
